prompt --application/shared_components/user_interface/templates/list/constellation_map
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(666365964619852425)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TConstellationMap #COMPONENT_CSS_CLASSES#" id="#LIST_ID#" data-zoom-in="Zoom in" data-zoom-out="Zoom out" data-fit="Show the whole map" data-list-view="List view" data-reset="Reset brightness" data-reset-done="Brightness reset" data-hint="Drag to pan, Ctrl + scroll or pinch to zoom, arrow keys move between stars" data-here="You are here" data-recent="Used recently" data-zoom="Zoom">',
'<ul class="amc-TConstellationMap-stars">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>'))
,p_list_template_current=>'<li class="amc-TConstellationMap-star is-current"><a class="amc-TConstellationMap-link" href="#LINK#" aria-current="page"><span class="amc-TConstellationMap-dot" aria-hidden="true"></span><span class="amc-TConstellationMap-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TConstellationMap-name">#TEXT#</span><span class="amc-TConstellationMap-sep">, </span><span class="amc-TConstellationMap-group">#A01#</span></a><span class="amc-TConstellationMap-desc">#A02#</span></li>'
,p_list_template_noncurrent=>'<li class="amc-TConstellationMap-star"><a class="amc-TConstellationMap-link" href="#LINK#"><span class="amc-TConstellationMap-dot" aria-hidden="true"></span><span class="amc-TConstellationMap-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TConstellationMap-name">#TEXT#</span><span class="amc-TConstellationMap-sep">, </span><span class="amc-TConstellationMap-group">#A01#</span></a><span class="amc-TConstellationMap-desc">#A02#</span></li>'
,p_list_template_name=>'AMC Constellation Map'
,p_internal_name=>'AMC_TPL_CONSTELLATION_MAP'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-constellation-map.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-constellation-map.css'
,p_a01_label=>'Constellation'
,p_a02_label=>'Description'
,p_list_template_comment=>'List template for a static or dynamic List region, flat lists. Put the group name in User Defined Attribute 1, for example Sales, Finance, Operations, Admin; entries with the same value form one constellation, joined by lines in list order, so keep each group''s entries together. Attribute 2 is a short description shown on the label card. With JavaScript the entries become stars on a sky: star positions come from the group and entry names, so the map looks the same on every visit and after adding an entry only its constellation changes. The current page glows with a breathing halo. Pointer hover or keyboard focus on a star shows a label card with the name, group and description. Pan by dragging, zoom with Ctrl or Cmd plus the mouse wheel, a trackpad pinch, two-finger pinch on touch, the Zoom in, Zoom out and Show the whole map buttons, or the plus, minus and 0 keys while focus is on the map; clicking a constellation name zooms to it. Plain mouse wheel keeps scrolling the page. Tab and Shift+Tab, and the arrow keys, Home and End, move focus between stars in list order, and the map pans to keep the focused star in view. The List view button, a toggle with aria-pressed, switches to the plain list, and the choice is remembered in this browser. Without JavaScript the entries are a grid of links, each labelled with its group and description. Template options: Recently used stars shine brighter counts each visit to a page of the list in this browser only, localStorage key amc-tpl-constellation-map, application id and list id, with a Reset brightness button; Night sky; Tall map; Still sky; Start in list view. Under prefers-reduced-motion nothing twinkles, drifts, breathes or glides. English strings to translate are data attributes on the wrapper in the Before List Entry part: data-zoom-in Zoom in, data-zoom-out Zoom out, data-fit Show the whole map, data-list-view List view, data-reset Reset brightness, data-reset-done Brightness reset, data-hint Drag to pan, Ctrl + scroll or pinch to zoom, arrow keys move between stars, data-here You are here, data-recent Used recently, data-zoom Zoom.'
);
end;
/
