,p_theme_id=>42
,p_name=>'RECENT'
,p_display_name=>'Recently used stars shine brighter'
,p_display_sequence=>10
,p_list_template_id=>wwv_flow_imp.id(666365964619852425)
,p_css_classes=>'amc-TConstellationMap--recent'
,p_template_types=>'LIST'
,p_help_text=>'Counts visits to the pages of this list in the browser''s localStorage, weighted towards recent use, and makes often used stars bigger and brighter while unused ones recede. Nothing leaves the browser; the toolbar gets a Reset brightness button.'
);
